sys_ux_data_broker_transform.script:
function transform(input) {
    var loginUser = input.userID;

	function isUserInGroup(userSysId, groupname) {
        var group = new GlideRecord('sys_user_grmember');
        group.addEncodedQuery("group.name=" + groupname + "^user=" + userSysId);
        group.query();

        // If a record is found, the user is a member of the group
        return group.next();
    }

	var hide=true;
	if (isUserInGroup(loginUser, 'GRC Senior Managers') || isUserInGroup(loginUser, 'GRC Managers')) {
        hide = false;
    } else {
       hide=true;
    }


	var emp = {};
	emp.hidden=hide;


    var employees = [{
        "id": "none",
        "label": "-- None --"
    }];
    // get employees under manager
    var user = new GlideRecord("sys_user");
    user.addEncodedQuery("active=true^roles=x_1324635_grc_ops.grc_interns^u_coach=" + loginUser + "^ORu_dev_leader=" + loginUser);
    user.query();
    while (user.next()) {
        employees.push({
            "id": user.sys_id.toString(),
            "label": user.name.getDisplayValue()
        });
    }

    emp.employee= employees;

	return emp;
}
